<template>
  <div class="container account-wrap">
    <div class="page-heading" style="padding-top:0"><div class="eyebrow">Your travel desk</div><h1>我的行程</h1><p>在这里管理个人信息、门票订单、评价和收藏的风景。</p></div>
    <section class="account-overview"><div class="account-welcome"><span class="eyebrow">TRAVEL DESK</span><strong>{{ profile.realName || profile.nickname || '旅行者' }}，准备好下一次出发了吗？</strong><small>{{ nextOrder ? `下一站是 ${nextOrder.scenicName}，游览日期为 ${nextOrder.visitDate}` : '收藏一个目的地，先把下一次旅行放进行程。' }}</small></div><div class="account-metrics"><div><strong>{{ orderStats.total }}</strong><span>全部订单</span></div><div><strong>{{ orderStats.pending }}</strong><span>待支付</span></div><div><strong>¥{{ walletBalance.toFixed(0) }}</strong><span>钱包余额</span></div><div><strong>{{ favorites.length }}</strong><span>收藏景点</span></div><div><strong>{{ comments.length }}</strong><span>我的评价</span></div></div></section>
    <div class="account-layout">
      <aside class="account-menu"><button v-for="item in menus" :key="item.key" :class="{ active: active === item.key }" @click="active = item.key"><el-icon style="vertical-align:-2px;margin-right:8px"><component :is="item.icon" /></el-icon>{{ item.label }}</button><button @click="logout" style="margin-top:18px;color:#b14c35"><el-icon style="vertical-align:-2px;margin-right:8px"><SwitchButton /></el-icon>退出账号</button></aside>
      <section class="account-panel">
        <template v-if="active === 'profile'"><h2>个人信息</h2><el-form :model="profile" label-position="top" style="max-width:520px"><el-form-item label="姓名"><el-input v-model="profile.realName" maxlength="50" placeholder="用于预订门票时自动填写联系人" /></el-form-item><el-form-item label="手机号"><el-input :model-value="profile.phone" disabled /><small class="form-tip">手机号将自动带入购票联系人信息</small></el-form-item><el-form-item label="昵称"><el-input v-model="profile.nickname" /></el-form-item><el-form-item label="头像"><div class="avatar-upload-row"><el-avatar :size="72" :src="profile.avatar">{{ profile.nickname?.slice(0, 1) }}</el-avatar><el-upload action="#" :show-file-list="false" :http-request="uploadAvatar" accept="image/*"><el-button :loading="avatarUploading"><el-icon><Upload /></el-icon>上传头像</el-button></el-upload></div><el-input v-model="profile.avatar" placeholder="也可以填写图片 URL" style="margin-top:10px" /></el-form-item><el-form-item label="新密码"><el-input v-model="profile.password" type="password" show-password placeholder="不修改请留空" /></el-form-item><el-button type="primary" @click="saveProfile">保存信息</el-button></el-form></template>
        <template v-else-if="active === 'orders'"><div class="account-section-head"><div><h2>我的订单</h2><p>记录每一次出发，待支付订单可以在这里继续完成。</p></div><el-select v-model="orderFilter" size="small" style="width:130px"><el-option label="全部订单" value="all"/><el-option label="待支付" value="PENDING"/><el-option label="已支付" value="PAID"/><el-option label="已完成" value="COMPLETED"/><el-option label="已取消" value="CANCELLED"/></el-select></div><div v-if="visibleOrders.length"><div v-for="order in visibleOrders" :key="order.id" class="order-row"><div><div class="order-name">{{ order.scenicName }}</div><div class="order-meta">订单号 {{ order.orderNo }}<br />游览日期 {{ order.visitDate }} · {{ order.ticketType || '成人票' }} · {{ order.quantity }} 张<span v-if="order.paymentMethod"> · {{ paymentMethodText(order.paymentMethod) }}</span></div></div><div class="order-meta">{{ order.contactName }}<br />{{ order.contactPhone }}</div><div class="order-price">¥{{ order.totalPrice }}<div><el-tag size="small" :type="statusType(order.status)">{{ statusText(order.status) }}</el-tag></div></div><div><el-button v-if="order.status === 'PENDING'" size="small" type="primary" link @click="pay(order)">去支付</el-button><el-button v-if="order.status === 'PENDING'" size="small" type="danger" link @click="cancel(order)">取消</el-button><el-button v-if="canReview(order)" size="small" type="success" link @click="openReview(order)">评价</el-button></div></div></div><div v-else class="empty-state">当前没有符合条件的订单，去发现一处想去的风景吧。</div></template>
        <template v-else-if="active === 'comments'"><h2>我的评价</h2><div v-if="comments.length"><div v-for="comment in comments" :key="comment.id" class="comment-row"><div class="comment-head"><el-rate v-model="comment.score" disabled /><span class="order-meta">{{ formatDate(comment.createTime) }}</span></div><div class="comment-content">{{ comment.content }}</div><div v-if="comment.images?.length" class="review-gallery"><el-image v-for="image in comment.images" :key="image" :src="image" fit="cover" :preview-src-list="comment.images" preview-teleported /></div><div v-if="comment.replies?.length" class="reply-thread"><div v-for="reply in comment.replies" :key="reply.id || reply.content" class="reply-item"><span>景区回复</span><div><strong>{{ reply.adminName || '景区客服' }}</strong><p>{{ reply.content }}</p><small>{{ formatDate(reply.createTime) }}</small></div></div></div></div></div><div v-else class="empty-state">完成一次旅行后，来写下你的体验。</div></template>
        <template v-else-if="active === 'wallet'"><div class="account-section-head"><div><h2>我的钱包</h2><p>用于课程项目中的门票余额支付，所有金额均为演示数据。</p></div><el-tag type="success" effect="light">账户正常</el-tag></div><section class="my-wallet-card"><div><span>可用余额</span><strong>¥{{ walletBalance.toFixed(2) }}</strong><small>余额已保存至 MySQL，支付后实时扣减</small></div><div class="wallet-card-mark"><el-icon><Wallet /></el-icon><span>行旅志旅行钱包</span><small>TRAVEL WALLET</small></div></section><div class="wallet-summary-grid"><div><span>钱包支付次数</span><strong>{{ walletOrders.length }}</strong></div><div><span>累计钱包支出</span><strong>¥{{ walletSpent.toFixed(2) }}</strong></div><div><span>待支付订单</span><strong>{{ orderStats.pending }}</strong></div></div><div class="wallet-record-head"><h3>钱包支付记录</h3><button type="button" @click="active='orders'">查看全部订单 →</button></div><div v-if="walletOrders.length" class="wallet-record-list"><div v-for="order in walletOrders" :key="order.id"><span class="wallet-record-icon">票</span><div><strong>{{ order.scenicName }}</strong><small>{{ formatDate(order.createTime) }} · {{ order.ticketType }} × {{ order.quantity }}</small></div><b>-¥{{ formatMoney(order.totalPrice) }}</b></div></div><div v-else class="empty-state">还没有钱包支付记录，预订门票时可选择钱包余额支付。</div></template>
        <template v-else><h2>我的收藏</h2><div v-if="favorites.length" class="scenic-grid" style="grid-template-columns:repeat(2,1fr)"><ScenicCard v-for="item in favorites" :key="item.id" :scenic="item" /></div><div v-else class="empty-state">把心动的目的地收藏起来吧。</div></template>
      </section>
    </div>
    <el-dialog v-model="reviewVisible" title="发表评价" width="min(520px, calc(100% - 30px))" destroy-on-close>
      <p style="margin-top:-4px;color:var(--muted)">{{ currentOrder?.scenicName }} · 分享你的旅行体验</p>
      <el-form ref="reviewRef" :model="reviewForm" :rules="reviewRules" label-position="top"><el-form-item label="评分" prop="score"><el-rate v-model="reviewForm.score" show-score score-template="{value} 分" /></el-form-item><el-form-item label="评价内容" prop="content"><el-input v-model="reviewForm.content" type="textarea" :rows="5" maxlength="1000" show-word-limit placeholder="说说景色、服务或游览体验吧" /></el-form-item><el-form-item label="添加照片（最多 6 张）"><el-upload action="#" :show-file-list="false" :http-request="uploadReviewImage" accept="image/jpeg,image/png,image/gif,image/webp" :disabled="reviewForm.images.length>=6"><el-button :loading="reviewUploading" plain><el-icon><Picture /></el-icon>上传实景照片</el-button></el-upload><div v-if="reviewForm.images.length" class="review-upload-grid"><div v-for="(image,index) in reviewForm.images" :key="image"><img :src="image"/><button type="button" @click="reviewForm.images.splice(index,1)"><el-icon><Close /></el-icon></button></div></div></el-form-item></el-form>
      <template #footer><el-button @click="reviewVisible = false">取消</el-button><el-button type="primary" :loading="reviewSubmitting" @click="submitReview">提交评价</el-button></template>
    </el-dialog>
    <el-dialog v-model="paymentVisible" title="选择支付方式" width="min(460px, calc(100% - 28px))" destroy-on-close>
      <div class="payment-order-summary"><span>{{ paymentOrder?.scenicName }}</span><strong>¥{{ paymentOrder?.totalPrice }}</strong><small>订单号：{{ paymentOrder?.orderNo }}</small></div>
      <el-radio-group v-model="paymentMethod" class="payment-methods"><el-radio-button value="wallet" label="wallet"><span class="payment-method"><b>💰</b><span><strong>钱包余额支付</strong><small>演示钱包余额 ¥{{ walletBalance.toFixed(2) }}</small></span></span></el-radio-button><el-radio-button value="scan" label="scan"><span class="payment-method"><b>▦</b><span><strong>扫码支付</strong><small>使用手机扫码完成演示支付</small></span></span></el-radio-button></el-radio-group>
      <div v-if="paymentMethod === 'scan'" class="payment-scan-box"><div class="payment-qr"><i v-for="n in 169" :key="n" :class="{dark: paymentQr[n - 1]}"/><span>行旅志</span></div><p>请使用手机扫描二维码<br/><small>课程演示二维码，不产生真实扣款</small></p></div>
      <div v-else class="wallet-balance-box"><span>当前演示钱包余额</span><strong>¥{{ walletBalance.toFixed(2) }}</strong><small>支付成功后订单状态将更新为“已支付”</small></div>
      <template #footer><el-button @click="paymentVisible=false">暂不支付</el-button><el-button type="primary" :loading="paymentSubmitting" @click="confirmPay">确认支付</el-button></template>
    </el-dialog>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { ChatDotRound, Close, Collection, Document, Picture, SwitchButton, Upload, User, Wallet } from '@element-plus/icons-vue'
import { commentApi, favoriteApi, orderApi, uploadApi, userApi } from '../../api/http'
import ScenicCard from '../../components/ScenicCard.vue'

const router = useRouter(); const active = ref('profile'); const orderFilter = ref('all'); const profile = reactive({ phone: '', nickname: '', realName: '', avatar: '', walletBalance: 0, password: '' }); const orders = ref([]); const comments = ref([]); const favorites = ref([]); const avatarUploading = ref(false); const reviewUploading = ref(false); const reviewVisible = ref(false); const reviewSubmitting = ref(false); const reviewRef = ref(); const currentOrder = ref(null); const reviewForm = reactive({ score: 5, content: '', images: [] }); const paymentVisible = ref(false); const paymentSubmitting = ref(false); const paymentOrder = ref(null); const paymentMethod = ref('wallet'); const paymentQr = computed(() => { const values=[]; for(let i=0;i<169;i++) values.push(((i*31+i%7*11+17)%13)<6); const mark=(x,y)=>{for(let dy=0;dy<5;dy++)for(let dx=0;dx<5;dx++)values[(y+dy)*13+x+dx]=dx===0||dx===4||dy===0||dy===4||(dx>1&&dx<4&&dy>1&&dy<4)};mark(0,0);mark(8,0);mark(0,8);return values })
const reviewRules = { score: [{ required: true, message: '请选择评分', trigger: 'change' }], content: [{ required: true, message: '请输入评价内容', trigger: 'blur' }, { min: 5, message: '评价至少 5 个字', trigger: 'blur' }] }
const menus = [{ key: 'profile', label: '个人信息', icon: User }, { key: 'orders', label: '我的订单', icon: Document }, { key: 'wallet', label: '我的钱包', icon: Wallet }, { key: 'comments', label: '我的评价', icon: ChatDotRound }, { key: 'favorites', label: '我的收藏', icon: Collection }]
const orderStats = computed(() => ({ total: orders.value.length, pending: orders.value.filter(item => item.status === 'PENDING').length }))
const visibleOrders = computed(() => orderFilter.value === 'all' ? orders.value : orders.value.filter(item => item.status === orderFilter.value))
const walletBalance = computed(() => Number(profile.walletBalance || 0))
const walletOrders = computed(() => orders.value.filter(item => item.paymentMethod === 'wallet' && ['PAID', 'COMPLETED'].includes(item.status)))
const walletSpent = computed(() => walletOrders.value.reduce((sum, item) => sum + Number(item.totalPrice || 0), 0))
const nextOrder = computed(() => orders.value.filter(item => item.status !== 'CANCELLED' && item.visitDate).sort((a,b) => String(a.visitDate).localeCompare(String(b.visitDate)))[0])
const load = async () => { const info = await userApi.info(); Object.assign(profile, info); const [myOrders, myComments, myFavorites] = await Promise.all([orderApi.mine(), commentApi.mine(), favoriteApi.mine()]); orders.value = myOrders; comments.value = myComments; favorites.value = myFavorites }
onMounted(load)
const saveProfile = async () => { const info = await userApi.update(profile); Object.assign(profile, info); profile.password = ''; window.dispatchEvent(new Event('user-profile-updated')); ElMessage.success('个人信息已保存') }
const uploadAvatar = async ({ file }) => { avatarUploading.value = true; try { profile.avatar = await uploadApi.image(file); ElMessage.success('头像已上传，点击“保存信息”后生效') } finally { avatarUploading.value = false } }
const pay = (order) => { paymentOrder.value = order; paymentMethod.value = 'wallet'; paymentVisible.value = true }
const confirmPay = async () => { if (!paymentOrder.value) return; if (paymentMethod.value === 'wallet' && Number(paymentOrder.value.totalPrice) > walletBalance.value) return ElMessage.warning('钱包余额不足，请选择扫码支付'); paymentSubmitting.value = true; try { const balance = await orderApi.pay(paymentOrder.value.id, paymentMethod.value); profile.walletBalance = Number(balance); paymentOrder.value.paymentMethod = paymentMethod.value; paymentOrder.value.status = 'PAID'; paymentVisible.value = false; ElMessage.success(paymentMethod.value === 'wallet' ? '钱包余额支付成功' : '扫码支付成功') } finally { paymentSubmitting.value = false } }
const cancel = async (order) => { await ElMessageBox.confirm('确定要取消这笔待支付订单吗？', '取消订单', { type: 'warning' }); await orderApi.cancel(order.id); order.status = 'CANCELLED'; ElMessage.success('订单已取消') }
const canReview = (order) => !comments.value.some(item => item.scenicId === order.scenicId)
const openReview = (order) => { currentOrder.value = order; reviewForm.score = 5; reviewForm.content = ''; reviewForm.images = []; reviewVisible.value = true }
const uploadReviewImage = async ({ file }) => { if (reviewForm.images.length >= 6) return; reviewUploading.value = true; try { reviewForm.images.push(await uploadApi.image(file)); ElMessage.success('照片已添加') } finally { reviewUploading.value = false } }
const submitReview = async () => { if (!await reviewRef.value.validate().catch(() => false)) return; reviewSubmitting.value = true; try { const comment = await commentApi.create({ scenicId: currentOrder.value.scenicId, score: reviewForm.score, content: reviewForm.content, images: [...reviewForm.images] }); comments.value.unshift(comment); reviewVisible.value = false; ElMessage.success('图文评价已提交') } finally { reviewSubmitting.value = false } }
const statusText = (status) => ({ PENDING: '待支付', PAID: '已支付', CANCELLED: '已取消', COMPLETED: '已完成' }[status] || status)
const statusType = (status) => ({ PENDING: 'warning', PAID: 'success', CANCELLED: 'info', COMPLETED: '' }[status] || 'info')
const paymentMethodText = method => ({ wallet:'钱包余额支付', scan:'扫码支付' }[method] || method)
const formatMoney = value => Number(value || 0).toFixed(2)
const formatDate = (value) => value ? String(value).replace('T', ' ').slice(0, 16) : ''
const logout = () => { sessionStorage.removeItem('user_token'); window.dispatchEvent(new Event('user-profile-updated')); router.push('/') }
</script>
